INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19601, 'Ezekiel 13:8', 'Ezekiel', 13, 8, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، ستاسو د دروغژنو خبرو او روياګانو په وجه، زۀ ستاسو خلاف يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19602, 'Ezekiel 13:9', 'Ezekiel', 13, 9, '&nbsp;زما لاس به د هغه نبيانو په خلاف وى څوک چې د دروغو روياګانې ګورى او د دروغو پالونه نيسى. هغوئ به زما د خلقو په ټولګى کښې شريک نۀ شى او نۀ به د بنى اِسرائيلو د قوم په فهرستونو کښې درج شى، او نۀ به هغوئ د اِسرائيل په مُلک کښې داخل شى. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک قادر مطلق خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19603, 'Ezekiel 13:10', 'Ezekiel', 13, 10, '&nbsp;ځکه چې هغوئ زما خلق ګمراهۍ خوا ته بوتلل، او وائى چې امن دے خو په حقيقت کښې امن نۀ وى. دا د هغه چا په شان دے لکه څوک چې کچه دېوال ووهى او بيا هغه نبيان ورته چونه ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19604, 'Ezekiel 13:11', 'Ezekiel', 13, 11, '&nbsp;نو په دې وجه هغه نبيانو ته ووايه څوک چې دا دېوالونه چونه کوى چې دا به راغورزيږى. زۀ به تېز باران او غټه ږلۍ راولېږم، او تېز باد به په دې رانازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19605, 'Ezekiel 13:12', 'Ezekiel', 13, 12, '&nbsp;کله چې دېوال راوغورزيږى، ولې خلق به ستاسو نه دا تپوس ونۀ کړى چې هغه سپينه چونه څۀ شوه چې تاسو دېوال ته ورکړې وه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19606, 'Ezekiel 13:13', 'Ezekiel', 13, 13, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى، په خپل قهر سره به زۀ يو وحشتناک طوفان راولېږم، او په خپل قهر سره به ږلۍ او د باران طوفان راولېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19607, 'Ezekiel 13:14', 'Ezekiel', 13, 14, '&nbsp;زۀ به هغه دېوال راوغورزوم کوم چې تاسو چونه کړے دے او هغه به زۀ د زمکې سره هوار کړم او د هغۀ بنياد به څرګند کړم. کله چې هغه راغورزيږى نو تاسو به هم په کښې تباه شئ، نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19608, 'Ezekiel 13:15', 'Ezekiel', 13, 15, '&nbsp;نو زۀ به خپل غضب په دېوال او په هغوئ سوړ کړم چا چې دېوال چونه کړے وو. نو زۀ به تاسو ته وايم چې، دېوال او هغه کسان دواړه فنا شو چا چې چونه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19609, 'Ezekiel 13:16', 'Ezekiel', 13, 16, '&nbsp;د اِسرائيل نبيانو ته چا چې د يروشلم په حقله پېشګوئې وکړه او د هغې په حقله يې د امن روياګانې ليدلې حال دا چې په رښتيا به امن نۀ وو، ما، مالِک خُدائ وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19610, 'Ezekiel 13:17', 'Ezekiel', 13, 17, '&nbsp;”اوس اے بنى آدمه، خپل مخ دې د دې ښځو په خلاف راواړوه څوک چې د خپلې خېټې نه نبوت کوى. د هغوئ خلاف نبوت وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19611, 'Ezekiel 13:18', 'Ezekiel', 13, 18, '&nbsp;او هغوئ ته ووايه چې مالِک قادر مطلق خُدائ داسې فرمائى چې، افسوس دې وى په هغه ښځو څوک چې په خپلو لاسونو سره د جادو او کوډو تعويذونه ګنډى او په خپل مړوند کښې يې راځوړندوى او د کوډو څادر جوړوى او چې خلق په خپل جال کښې ګرفتار کړى. آيا تاسو به زما د خلقو دپاره جال خور کړئ او خپل ژوند به بچ کړئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19612, 'Ezekiel 13:19', 'Ezekiel', 13, 19, '&nbsp;تاسو زما د خلقو په مينځ کښې د لږو اوربشو او د يو څو ټوکړو روټۍ دپاره زما بې‌حرمتى وکړه. تاسو زما غوره شوى خلقو ته دروغ ووئيل او هغوئ هم په تاسو باور وکړو او دغه شان تاسو هغوئ ووژل څوک چې د وژولو نۀ وو او هغوئ مو ژوندى پرېښودل څوک چې د ژوندى پرېښودلو نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19613, 'Ezekiel 13:20', 'Ezekiel', 13, 20, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ ستاسو د جادو منتر خلاف يم په کومو چې تاسو خلق لکه د مرغۍ راګېروئ او هغه به زۀ ستاسو د مټو نه خلاص کړم، او زۀ به هغه خلق آزاد کړم کوم چې تاسو لکه د مرغۍ په شان راګېر کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19614, 'Ezekiel 13:21', 'Ezekiel', 13, 21, '&nbsp;زۀ به ستاسو د جادو نقابونه وشلوم او خپلو خلقو له به ستاسو د لاسه خلاصون ورکړم، او هغوئ به نور ستاسو د جادو په اثر کښې نۀ راځى. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19615, 'Ezekiel 13:22', 'Ezekiel', 13, 22, '&nbsp;تاسو د خپلو دروغو په وجه صادقان بې‌زړۀ کړل اګر چې ما هغوئ ته هيڅ قسم تکليف نۀ دے ورکړے، او تاسو ګناهګارانو ته ډاډ ورکوئ چې د خپلو بدو لارو نه راونۀ ګرځى او د هغوئ ژوند بچ نۀ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19616, 'Ezekiel 13:23', 'Ezekiel', 13, 23, '&nbsp;نو په دې وجه تاسو به نور نۀ د دروغو رويا وګورئ او نۀ به فالګرى وکړئ. زۀ به خپل خلق ستاسو د لاسه بچ کړم. او بيا به تاسو پوهه شئ چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19617, 'Ezekiel 14:1', 'Ezekiel', 14, 1, '&nbsp;نو بيا د اِسرائيل ځينې مشران ما له راغلل او زما په وړاندې کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19618, 'Ezekiel 14:2', 'Ezekiel', 14, 2, '&nbsp;نو د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19619, 'Ezekiel 14:3', 'Ezekiel', 14, 3, '&nbsp;”اے بنى آدمه، دې مشرانو په خپل زړۀ کښې بُتانو له ځائ ورکړے دے او هغوئ هغه د خپل ځان په وړاندې د ګناه او تيندک خوړلو سبب ګرځولے دے. نو بيا ولې زۀ دوئ ته غوږ ونيسم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19620, 'Ezekiel 14:4', 'Ezekiel', 14, 4, '&nbsp;نو په دې وجه هغوئ سره خبره وکړه او هغوئ ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې کله چې يو بنى اِسرائيلى خپل زړۀ کښې بُتانو له ځائ ورکړے وى او د خپل ځان د وړاندې يې د ګناه او تيندک خوړلو سبب ګرځولے وى او بيا يو نبى ته د مشورې دپاره ورشى، نو بيا به زۀ مالِک خُدائ هغۀ له په خپله داسې جواب ورکړم چې د هغوئ د ډيرې بُت پرستۍ لائق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19621, 'Ezekiel 14:5', 'Ezekiel', 14, 5, '&nbsp;زۀ به دا د دې دپاره وکړم چې د خپلو خلقو بنى اِسرائيلو په زړونو دوباره قبضه وکړم، ټولو چا چې زۀ د خپلو بُتانو په وجه پرېښودے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19622, 'Ezekiel 14:6', 'Ezekiel', 14, 6, '&nbsp;نو په دې وجه د بنى اِسرائيلو قوم ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې، توبه وکړئ، او د خپلو بُتانو نه راوګرځئ او د خپلو ټولو حرامو کارونو نه منع شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19623, 'Ezekiel 14:7', 'Ezekiel', 14, 7, '&nbsp;هرکله کۀ يو بنى اِسرائيلے او يا غېر مُلکى په اِسرائيل کښې اوسيږى او خپل ځان يې زما نه جدا کړے وى او بُتانو له يې په خپل زړۀ کښې ځائ ورکړے وى او د خپل ځان د وړاندې يې د ګناه او تيندک خوړلو سبب ګرځولے وى او بيا يو نبى له د مشورې دپاره ورشى او زما په حقله ترې تپوس وکړى، نو زۀ مالِک خُدائ به په خپله هغوئ له جواب ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19624, 'Ezekiel 14:8', 'Ezekiel', 14, 8, '&nbsp;زۀ به د داسې کس مخالفت کوم او نورو خلقو ته به يې د خندا مثال جوړ کړم. او زۀ به هغه د خپل قوميت نه وباسم. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19625, 'Ezekiel 14:9', 'Ezekiel', 14, 9, '&nbsp;او کۀ هغه نبى په پېشګويۍ ورکولو کښې دوکه شى او دروغ ووائى نو ما مالِک خُدائ هغه نبى له دوکه ورکړه، او زۀ به خپل لاس د هغۀ خلاف وراوږد کړم او هغه به د خپلو خلقو بنى اِسرائيلو نه نيست و نابود کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19626, 'Ezekiel 14:10', 'Ezekiel', 14, 10, '&nbsp;هغوئ دواړو ته به د خپلې ګناه سزا مِلاو شى، پېغمبر ته او هم هغه چا ته چې پېغمبر ته د هدايت حاصلولو دپاره راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19627, 'Ezekiel 14:11', 'Ezekiel', 14, 11, '&nbsp;نو بيا به د بنى اِسرائيلو خلق زما نه نور نۀ بې‌لارې کيږى، او نۀ به هغوئ نور خپل ځانونه په ډېرو ګناهونو کولو باندې پليتوى. هغوئ به زما خلق وى، او زۀ به د هغوئ خُدائ يم، مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19628, 'Ezekiel 14:12', 'Ezekiel', 14, 12, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19629, 'Ezekiel 14:13', 'Ezekiel', 14, 13, '&nbsp;”اے بنى آدمه، کۀ چرې يو مُلک زما خلاف ګناه او بې‌وفائى وکړى او زۀ خپل لاس د هغوئ خلاف اوچت کړم او د هغوئ رزق بند کړم او په هغوئ باندې قحط نازل کړم او د هغه مُلک سړى او ځناور مړۀ کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19630, 'Ezekiel 14:14', 'Ezekiel', 14, 14, '&nbsp;کۀ چرې نوح، دانيال، او ايُوب درې واړه هم هلته اوسېدل، نو هغوئ به په خپل صداقت صرف خپل ځانونه بچ کړى وُو، مالِک قادر مطلق خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19631, 'Ezekiel 14:15', 'Ezekiel', 14, 15, '&nbsp;او يا کۀ چرې زۀ هغه مُلک ته ځنګلى ځناور ورولېږم چې د هغې خلق ووژنى او مُلک بلکل وران ويجاړ کړى، نو بيا به د هغه ځناورو په وجه هيڅ څوک هم د هغه مُلک نه نۀ شى تېرېدلے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19632, 'Ezekiel 14:16', 'Ezekiel', 14, 16, '&nbsp;زما دې په خپل ذات قسم وى، قادر مطلق مالِک خُدائ فرمائى، کۀ چرې دا درې واړه کسان هم هلته اوسېدل نو هغوئ به خپل زامن او لوڼه هم نۀ شُو بچ کولے. يواځې هغوئ به بچ شى خو ټول مُلک به وران ويجاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19633, 'Ezekiel 14:17', 'Ezekiel', 14, 17, '&nbsp;او کۀ چرې زۀ په هغه مُلک جنګ راولم، او ووايم چې پرېږده چې تُوره د ټول مُلک نه تېره شى او زۀ په کښې انسانان او د دوئ ځناور مړۀ کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19634, 'Ezekiel 14:18', 'Ezekiel', 14, 18, '&nbsp;زما دې په خپل ذات قسم وى، قادر مطلق مالِک خُدائ فرمائى، کۀ چرې دا درې واړه کسان په دې کښې اوسېدل، بيا هم دوئ خپل زامن او لوڼه نۀ شُو بچ کولے. خو صرف دوئ به بچ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19635, 'Ezekiel 14:19', 'Ezekiel', 14, 19, '&nbsp;او يا فرض کړئ کۀ چرې زۀ په دغه مُلک وبا رانازله کړم او خپل غضب پرې د وينې توېدو په ذريعه نازل کړم چې د دې سړى او ځناور مړۀ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19636, 'Ezekiel 14:20', 'Ezekiel', 14, 20, '&nbsp;زما دې په خپل ذات قسم وى، مالِک قادر مطلق خُدائ فرمائى، کۀ چرې نوح، دانيال او ايُوب هم په دې کښې اوسېدل، هغوئ خپل زامن او لوڼه نۀ شول بچ کولے. بلکې هغوئ به په خپل صداقت سره صرف خپل ځانونه بچ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19637, 'Ezekiel 14:21', 'Ezekiel', 14, 21, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، دا به د يروشلم دپاره څومره خراب وخت وى کله چې زۀ خپل دا څلور سخت يروونکى عذابونه د هغوئ خلاف ورولېږم، جنګ او قحط او وحشى ځناور او وباګانې چې د دې سړى او ځناور مړۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19638, 'Ezekiel 14:22', 'Ezekiel', 14, 22, '&nbsp;خو بيا هم به څۀ کسان ژوندى پاتې شى خو هغوئ به تاسو سره په جلاوطنۍ کښې يوځائ شى. کله چې تاسو په خپله د هغوئ بد عملونه وګورئ، نو بيا به تاسو په خپله ووايئ چې کوم افتونه ما په يروشلم نازل کړى وُو هغه ضرورى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19639, 'Ezekiel 14:23', 'Ezekiel', 14, 23, '&nbsp;تاسو به په خپله مطمئن شئ کله چې تاسو د هغوئ چال چلن او د هغوئ کردار وګورئ، نو تاسو به په دې پوهه شئ چې ما بې د کومې وجې په هغوئ باندې تکليف او افت نۀ دے نازل کړے. ما، مالِک قادر مطلق خُدائ وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19640, 'Ezekiel 15:1', 'Ezekiel', 15, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19641, 'Ezekiel 15:2', 'Ezekiel', 15, 2, '&nbsp;”اے بنى آدمه، د انګور د بوټى څانګه د ځنګل د نورو ونو څانګو نه په کوم لحاظ سره ښۀ ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19642, 'Ezekiel 15:3', 'Ezekiel', 15, 3, '&nbsp;آيا د دې لرګے د کوم شى د جوړولو دپاره استعمالولے شى؟ ولې هغوئ د دې نه موږى جوړوى چې څيزونه پرې راځوړند کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19643, 'Ezekiel 15:4', 'Ezekiel', 15, 4, '&nbsp;او کله چې هغه په اور کښې د سوزولو دپاره وغورزولے شى او اور د دې دواړه سرونه وسوزوى او مينځ يې په سکرو بدل شى، آيا دا بيا د څۀ شى دپاره په کار راځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19644, 'Ezekiel 15:5', 'Ezekiel', 15, 5, '&nbsp;د سوزېدو نه مخکښې چې دا د هيڅ کار نۀ وو، نو بيا به دا څومره بې‌کاره وى کله چې دا په اور کښې وسوزيږى او سکارۀ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19645, 'Ezekiel 15:6', 'Ezekiel', 15, 6, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، لکه څنګه چې ما د انګور بوټى د ځنګل په بوټو کښې ورکړو چې د خشاک دپاره استعمال شى نو هم دغه شان سلوک به زۀ د هغوئ سره وکړم څوک چې په يروشلم کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19646, 'Ezekiel 15:7', 'Ezekiel', 15, 7, '&nbsp;زۀ به خپل مخ د هغوئ خلاف کړم، اګر کۀ هغوئ د اور نه بهر راوتل خو اور به بيا هم هغوئ وسوزوى. نو کله چې زۀ خپل مخ د هغوئ خلاف کړم، نو تاسو به پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19647, 'Ezekiel 15:8', 'Ezekiel', 15, 8, '&nbsp;زۀ به هغه زمکه ورانه ويجاړه کړم ځکه چې هغوئ زما سره بې‌وفائى کړې ده، دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19648, 'Ezekiel 16:1', 'Ezekiel', 16, 1, '&nbsp;نو د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19649, 'Ezekiel 16:2', 'Ezekiel', 16, 2, '&nbsp;”اے بنى آدمه، يروشلم د خپل حرام کار په حقله خبر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19650, 'Ezekiel 16:3', 'Ezekiel', 16, 3, '&nbsp;او ورته ووايه، مالِک خُدائ يروشلم ته داسې فرمائى، ستاسو نسل او پېدايښت د کنعان د مُلک دے، ستاسو پلار امورى وو او ستاسو مور حِتى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19651, 'Ezekiel 16:4', 'Ezekiel', 16, 4, '&nbsp;په هغه ورځ کله چې تۀ پېدا شوې، نو هيچا ستا نوم پرې نۀ کړو او نۀ چا په اوبو ولمبولې چې پاک دې کړى، او نۀ په تا چا مالګه ومږله او نۀ تۀ چا په اورڼى کښې ونغښتې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19652, 'Ezekiel 16:5', 'Ezekiel', 16, 5, '&nbsp;نو چا هم تا ته د رحم په سترګه ونۀ کتل او په تا باندې چا زړۀ هم ونۀ سوزولو چې دا کارونه درته وکړى. ستا د پېدا کېدو د ورځې نه هغوئ تا نه نفرت کولو او تۀ يې په يو مېدان کښې وروغورزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19653, 'Ezekiel 16:6', 'Ezekiel', 16, 6, '&nbsp;نو زۀ په دغه ځائ تېر شوم او ومې ليدلې چې په خپلو وينو کښې دې لتې وهلې، نو کله چې تۀ په وينو کښې ککړ پروت وې نو ما درته وفرمائيل چې ژوندۍ اوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19654, 'Ezekiel 16:7', 'Ezekiel', 16, 7, '&nbsp;ما تۀ لکه د بوټى په شان لويه کړې. تۀ لويه شوې او لوړه دنګه شوې او يوه پېغله درنه جوړه شوه، ستا سينې راوشوې، او ستا د سر وېښتۀ رالوئ شُو خو تۀ لا تر اوسه بربنډه او لغړه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19655, 'Ezekiel 16:8', 'Ezekiel', 16, 8, '&nbsp;لږ وروستو زۀ په تا تېرېدم، نو کله چې ما تا ته وکتل نو ومې ليدلې چې تۀ د مينې کولو قابله شوې، ما د خپلو جامو يو حِصه په تا وغوړوله او ستا شرم مې پټ کړو. ما قسم وخوړلو او تا سره مې لوظ وکړو، مالِک قادر مطلق خُدائ وفرمائيل، او تۀ زما شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19656, 'Ezekiel 16:9', 'Ezekiel', 16, 9, '&nbsp;تۀ ما په اوبو ولمبولې او ستا نه مې وينه صفا کړه او ستا په بدن مې تېل ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19657, 'Ezekiel 16:10', 'Ezekiel', 16, 10, '&nbsp;ما تا ته د ګُلکارۍ جامې درواغوستلې او د څرمنې پېزار مې درته په پښو کړو. ما درته ښکلې د کتان او د رېښمو قيمتى جامې درواغوستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19658, 'Ezekiel 16:11', 'Ezekiel', 16, 11, '&nbsp;ما تۀ په کالو سنګار کړې، ما ستا په لاس کښې بنګړى او په غاړه کښې مې درته اميل واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19659, 'Ezekiel 16:12', 'Ezekiel', 16, 12, '&nbsp;او ما په پوزه کښې درته نتکۍ او په غوږونو کښې مې والۍ درته واچولې او ښائسته تاج مې در په سر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19660, 'Ezekiel 16:13', 'Ezekiel', 16, 13, '&nbsp;نو تۀ په سپينو او سرو زرو سنګار شوې، تا د قيمتى کتان او ګُلکارۍ جامې واغوستې. ستا خوراک ښۀ اوړۀ، شات او د زيتُونو تېل وُو. تۀ ډېره ښکلې شوې او ستا نه مَلِکه جوړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19661, 'Ezekiel 16:14', 'Ezekiel', 16, 14, '&nbsp;او ستا د ښُکلا مشهورتيا په نورو قومونو کښې ډنډوره شوه، ستا ښائست کامِل وو ځکه چې ما د خپل شان او شوکت نه تا له دا درکړى وُو، قادر مطلق خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19662, 'Ezekiel 16:15', 'Ezekiel', 16, 15, '&nbsp;خو تا په خپله ښُکلا او شُهرت باندې بهروسه وکړه او خپل شُهرت دې د کنجرتوب دپاره استعمال کړو. ستا د کنجرتوب نه څوک هم په لار بچ نۀ شُو او خپل حسن دې باد کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19663, 'Ezekiel 16:16', 'Ezekiel', 16, 16, '&nbsp;تا خپلې جامې واخستې او په خپلو جامو دې زيارت رنګينه کړو، هلته دې کنجرتوب شروع کړو. نۀ داسې کارونه مخکښې شوى وُو او نۀ به وروستو وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19664, 'Ezekiel 16:17', 'Ezekiel', 16, 17, '&nbsp;تا خپل ځان سره قيمتى کالى هم واخستل کوم چې ما تا له درکړى وُو، کوم چې ما د سرو او سپينو زرو نه جوړ کړى وُو، او تا د هغوئ نه ځانله نارينه بُتان جوړ کړل او د هغوئ سره په زنا کولو مصروفه شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19665, 'Ezekiel 16:18', 'Ezekiel', 16, 18, '&nbsp;او تا په هغوئ باندې خپلې د کار جامې وغوړولې او تا هغوئ ته زما د تېلو او خوشبويۍ نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19666, 'Ezekiel 16:19', 'Ezekiel', 16, 19, '&nbsp;کوم خوراک چې ما تاسو ته د خوړلو دپاره درکړے وو، لکه ښۀ اوړۀ، د زيتُونو تېل او شات ما تاسو ته د خوړلو دپاره درکړل، خو تاسو هغه بُتانو ته د خوشبويۍ د نذرانو په شکل وړاندې کړل. دا د مالِک قادر مطلق خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19667, 'Ezekiel 16:20', 'Ezekiel', 16, 20, '&nbsp;او تاسو خپل زامن او لوڼه بوتلل کوم چې تاسو زما دپاره پېدا کړى وُو او هغوئ مو د خوراک په توګه بُتانو ته قربانى کړل. ولې ستا خپله زناکارى کافى نۀ وه څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19668, 'Ezekiel 16:21', 'Ezekiel', 16, 21, '&nbsp;تا زما بچى حلال کړل او بُتانو ته دې قربانى کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19669, 'Ezekiel 16:22', 'Ezekiel', 16, 22, '&nbsp;ستا په ټولو حرامو کارونو او ستا په زناکارۍ کښې تا ته خپل د ځوانۍ عمر ياد نۀ وو، کله چې تۀ بربنډه او لغړه وې او په خپلو وينو کښې دې لتې وهلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19670, 'Ezekiel 16:23', 'Ezekiel', 16, 23, '&nbsp;”افسوس، افسوس دې وى په تاسو، مالِک قادر مطلق خُدائ فرمائى. د دې باوجود ستاسو د خپلو نورو ټولو شرارتونو سره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19671, 'Ezekiel 16:24', 'Ezekiel', 16, 24, '&nbsp;تا په هر يو چوک کښې د ځان دپاره زيارتونه او بُت‌خانې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19672, 'Ezekiel 16:25', 'Ezekiel', 16, 25, '&nbsp;تا د سړک په هر يو ګوټ کښې بُت‌خانې جوړې کړې او خپله بې‌حرمتى دې وکړه او په لاره هر يو تېرېدونکى ته دې پښې ورتېرې کړې او هغوئ سره دې کنجرتوب وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19673, 'Ezekiel 16:26', 'Ezekiel', 16, 26, '&nbsp;تۀ د خپلو شهوت پرستو ګاونډيانو مِصريانو سره په زناکارۍ کښې آخته شوې، او تا د ډيرې زنا کولو په وجه زما قهر او غضب راوپارولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19674, 'Ezekiel 16:27', 'Ezekiel', 16, 27, '&nbsp;نو بيا ما خپل لاس ستا خلاف دراوږد کړو او ستا ملکيت مې کم کړو، او ما تۀ خپلو حرصناکو دشمنانو ته حواله کړې، يعنې د فلستيه لوڼو ته چا ته چې ستا د بې‌حيا کارونو نه حيا ورتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19675, 'Ezekiel 16:28', 'Ezekiel', 16, 28, '&nbsp;تۀ د اسوريانو سره هم په زناکارۍ کښې مصروفه شوې، ځکه چې ستا شوق نۀ پوره کېدو، بلکې د دې نه وروستو هم تۀ يخه نۀ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19676, 'Ezekiel 16:29', 'Ezekiel', 16, 29, '&nbsp;نو بيا تا خپله زناکارى د بابليانو مُلک پورې اوږده کړه، چې د سوداګرو مُلک دے، خو هغوئ هم ستا شوق پوره نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19677, 'Ezekiel 16:30', 'Ezekiel', 16, 30, '&nbsp;مالِک قادر مطلق خُدائ فرمائى چې تۀ د زړۀ نه څومره مجبوره يې چې تا لکه د بې‌حيا کنجرې په شان کارونه وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19678, 'Ezekiel 16:31', 'Ezekiel', 16, 31, '&nbsp;کله چې تا خپلې بُت‌خانې د کوڅې په هر ګوټ کښې جوړې کړې او په هر چوک کښې دې د خپل ځان دپاره زيارتونه جوړ کړل، تۀ د عام کنجرې په شان نۀ وې ځکه چې تا پېسې اخستل بد ګڼل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19679, 'Ezekiel 16:32', 'Ezekiel', 16, 32, '&nbsp;تۀ هغه زناکاره ښځه يې چې د خپل خاوند په ځائ پردو سړو سره بدکارى کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19680, 'Ezekiel 16:33', 'Ezekiel', 16, 33, '&nbsp;هره يوه کنجره پېسې اخلى، خو تۀ خپلو عاشقانو له تحفې ورکوې، هغوئ له خرچه ورکوې چې تا له د هرې خوا نه د ناروا کارونو دپاره راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19681, 'Ezekiel 16:34', 'Ezekiel', 16, 34, '&nbsp;نو تۀ په خپلې زناکارۍ کښې د نورو نه بدله يې. ستا د شوق دپاره هيڅ څوک تا پسې نۀ ګرځى. تۀ بلکل د نورو نه بدله يې، ځکه چې تۀ خرچه ورکوې خو تۀ په خپله څۀ نۀ اخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19682, 'Ezekiel 16:35', 'Ezekiel', 16, 35, '&nbsp;نو بيا تۀ اے زناکارې، د مالِک خُدائ کلام ته غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19683, 'Ezekiel 16:36', 'Ezekiel', 16, 36, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ځکه چې تا خپل مال دولت په خپلو عاشقانو خرچ کړو او خپله حيا دې د بدکارۍ په وخت کښې څرګنده کړه، ستا د ټولو خرابو بُتانو په وجه، ځکه چې تا هغوئ ته د خپلو بچو وينه پېش کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19684, 'Ezekiel 16:37', 'Ezekiel', 16, 37, '&nbsp;نو په دې وجه به زۀ ستا ټول عاشقان يو ځائ ته راغوڼد کړم، د چا نه چې تا خوندونه اخستل، د چا سره چې تا مينه کوله او هغوئ د چا نه چې تا نفرت کولو. زۀ به ستا ټول دشمنان د هر ځائ نه راغونډ کړم او د هغوئ په وړاندې به دې بربنډه کړم تر هغې چې هغوئ ټول تا په مکمل توګه لغړه وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19685, 'Ezekiel 16:38', 'Ezekiel', 16, 38, '&nbsp;زۀ به تا ته د هغه ښځو سزا درکړم چا چې زنا کړې ده او چا چې وينه تويه کړې ده، زۀ به تا نه په خپل غېرت او قهر او غضب کښې د قتل کولو بدله واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19686, 'Ezekiel 16:39', 'Ezekiel', 16, 39, '&nbsp;نو بيا به زۀ تا خپلو عاشقانو ته حواله کړم، او هغوئ به ستا بُت‌خانې ورانې کړى او ستا زيارتونه به تباه کړى. او هغوئ به ستا نه جامې او قيمتى کالى کوز کړى او بربنډه او لغړه به دې پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19687, 'Ezekiel 16:40', 'Ezekiel', 16, 40, '&nbsp;هغوئ به ستا خلاف جلوس راوکاږى څوک چې به تا سنګسار کړى او تا به په خپلو تُورو سره ټوټه ټوټه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19688, 'Ezekiel 16:41', 'Ezekiel', 16, 41, '&nbsp;هغوئ به ستا کورونه وسوزوى او د ډېرو ښځو په وړاندې به تا له سزا درکړى. زۀ به ستا کنجرتوب بند کړم. او تۀ به نور خپلو عاشقانو له پېسې نۀ ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19689, 'Ezekiel 16:42', 'Ezekiel', 16, 42, '&nbsp;نو بيا به زما غصه سړه شى او زما د غېرت قهر به سوړ شى، او زۀ به په آرام شم او نور به تا ته نۀ غصه کېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19690, 'Ezekiel 16:43', 'Ezekiel', 16, 43, '&nbsp;ځکه چې تا ته د خپلې ځوانۍ ورځې يادې نۀ دى خو زۀ تا په دې څيزونو سره غصه کړم. تا چې کوم بد عملونه کړى دى زۀ به د هغې ټولو بدله ستا نه واخلم، مالِک قادر مطلق خُدائ فرمائى. ته د خپلې ټولې حرام کارۍ سره په شهوت پرستۍ کښې د حد نه تېره شوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19691, 'Ezekiel 16:44', 'Ezekiel', 16, 44, '&nbsp;”هر څوک چې متلونه وائى نو دا متل به ستا په حقله وائى چې، څنګه يې مور وى هغسې يې لور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19692, 'Ezekiel 16:45', 'Ezekiel', 16, 45, '&nbsp;تۀ د خپلې مور رښتينې لور يې، چا چې د خپل خاوند نه او د خپلو ماشومانو نه نفرت وکړو، او تۀ د خپلې خور رښتينې خور يې، چا چې د خپلو خاوندانو او ماشومانو نه کرکه کوله، ستا مور حِتى وه او ستا پلار امورى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19693, 'Ezekiel 16:46', 'Ezekiel', 16, 46, '&nbsp;ستا مشره خور سامريه وه، څوک چې ستا شمال خوا ته خپلو لوريانو سره اوسيږى، او ستا کشره خور څوک چې په جنوب کښې د خپلو لوريانو سره اوسيږى، هغه سدوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19694, 'Ezekiel 16:47', 'Ezekiel', 16, 47, '&nbsp;دا نۀ چې تۀ صرف د هغوئ په نقش قدم باندې روانه يې او د هغوئ د حرامو کارونو پيروى دې وکړه بلکې په خپلو ټولو کردارونو کښې تۀ ډېره زر د هغوئ نه بدتره شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19695, 'Ezekiel 16:48', 'Ezekiel', 16, 48, '&nbsp;مالِک قادر مطلق خُدائ فرمائى چې، زما دې په خپل ذات قسم وى، تر دې چې ستا خور سدوم او د هغې لوريانو کله هم داسې بد کارونه نۀ وُو کړى کوم چې تا او ستا لوريانو وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19696, 'Ezekiel 16:49', 'Ezekiel', 16, 49, '&nbsp;نو د ستا د خور سدوم ګناه وه چې، هغې او د هغې لوڼو کبر کولو، او هغوئ خېټه ورې وې او د آرام ژوند يې تېرولو، خو د غريبو او ضرورتمندو سره يې امداد نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19697, 'Ezekiel 16:50', 'Ezekiel', 16, 50, '&nbsp;هغوئ کبرژن وُو او حرام کارونه يې زما په وړاندې وکړل. نو په دې وجه ما هغوئ لرې کړل لکه څنګه چې تاسو وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19698, 'Ezekiel 16:51', 'Ezekiel', 16, 51, '&nbsp;سامريې ستا د ګناه په نيمه حِصه هم ګناه نۀ ده کړې، تا د هغوئ نه ډېر زيات حرام کارونه کړى دى، او کوم حرام کارونه چې تا کړى دى تا خپلې خوېندې د هغوئ په نسبت وبخښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19699, 'Ezekiel 16:52', 'Ezekiel', 16, 52, '&nbsp;نو تۀ اوس په شرم وشرمېږه، ستا ګناهونه دومره خراب دى چې تا خپلې خوېندې وبخښلې او هغه دې صادقه وګرځولې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19700, 'Ezekiel 16:53', 'Ezekiel', 16, 53, '&nbsp;”خو زۀ به د سدوم او د هغې د لوريانو ژوندون دوباره بحال کړم او د سامريه او د هغې د لوريانو ژوندون به هم بحال کړم او ستا حالت به هم ورسره ښۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');